    }

    // 'turma' pode vir com IDs inteiros
    $raw = filter_input(INPUT_GET, 'turma');
    if (is_array($raw)) {
        $f['turma'] = array_map('intval', array_filter($raw, function ($v) { return trim((string) $v) !== ''; }));
