// ----- 3) Cláusula WHERE montada UMA ÚNICA vez ------
function clausulaIn(array $valores, string $coluna, &$tipos, &$params): string
{
    if (empty($valores)) {
        return '';
    }
    $qtd      = count($valores);
    $tipo     = is_int($valores[0]) ? 'i' : 's';   // id (inteiro) x texto
    $tipos    = str_repeat($tipo, $qtd);

    foreach ($valores as $v) {
        $params[] = $v; // SEMPRE passa por query preparada
    }

    return "$coluna IN (" . implode(',', array_fill(0, $qtd, '?')) . ")";
}

$whereClauses = [];
