function cacheDaLista(string $rotulo, callable $fornecedora): array
{
    $dir    = sys_get_temp_dir() . '/turmas_app';
    @mkdir($dir, 0755, true);
    $arq    = sprintf('%s/opcoes_%s.cache', $dir, md5($rotulo) . ':' . time());

    if (file_exists($arq)) {
        $d = json_decode(file_get_contents($arq), true);
        if (isset($d['dados']) && (time() - ($d['hora'] ?? 3600)) < ($d['duracao'] ?? 3600)) {
            return $d['dados'];
        }
        @unlink($arq);
    }

    $dados = $fornecedora();
    file_put_contents($arq, json_encode(['dados' => $dados, 'hora' => time(), 'duracao' => 3600], JSON_THROW_ON_ERROR), LOCK_EX);
