<?php
// db_connect.php deve retornar Instância PDOException se falhar
require __DIR__ . '/db_connect.php';

class TurmasFilter {
    private PDO $pdo;
    private int $rowsAffected;

    public function __construct() {
        try {
            $this->pdo = require __DIR__ . '/db_connect.php';
            $this->pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        } catch (PDOException $e) {
            Logger::log("Falha na conexão ao banco: ", $e);
            die(json_encode(['error' => $e->getMessage()]), JSON_UNESCAPED_UNICODE | JSON_UNENCODE);
        }
    }

    /**
     * Filtra turmas conforme os filtros fornecidos.
     * @param array $filters ex ['gre'=>[], 'escola'=>[], 'professor'=>[], 'turma'=>[]]
     * @return \PDOStatement|false
     */
    public function buscarTurmas(array $filters): ?PDOStatement {
        $whereClauses = [];
        $params = [];
        $types = [];
        $conditions = [
            ['col' => 'gre',  'op' => 'IN', 'val' => $filters['gre']],
            ['col' => 'escola', 'op' => 'IN', 'val' => $filters['escola']],
            ['col' => 'professor', 'op' => 'IN', 'val' => $filters['professor']],
            ['col' => 'id',     'op' => 'IN', 'val' => $filters['turma']],
        ];

        foreach ($conditions as $c) {
            if (empty($c['val'])) {
                continue;
            }
            $n = count($c['val']);
            $types[] = str_repeat('s', $n);
            for ($i = 0; $i < $n; ++$i) {
                $params[] = $c['val'][$i];
            }
            $placeholders = str_repeat('?,', $n - 1) . '?';
            $whereClauses[] = "$c['col'] IN ($placeholders)";
        }

        $where = !empty($whereClauses) ? 'WHERE ' . implode(' AND ', $whereClauses) : '';
        $sql = "SELECT * FROM turmas $where ORDER BY turma LIMIT 1000 OFFSET {$this->getOffset()}";
        // Paginação seria implementada aqui

        $stmt = $this->pdo->prepare($sql);
        if ($stmt === false) {
            Logger::log("Erro SQL: ", $this->pdo->errorCode, $this->pdo->errorMessage);
            return false;
        }
        $stmt->bind_param($types, ...$params);
        $stmt->execute();
        return $stmt;
    }

