declare(strict_types=1);

function montarOnde(array $condicoes, &$params, &$types): string {
    $clausulas = [];
    foreach ($condicoes as [$col, $valores]) {
        if (empty($valores)) continue;
        $n = count($valores);
        $types .= str_repeat('s', $n);
        for ($i = 0; $i < $n; ++$i) {
            $params[] = $valores[$i];
        }
        $clausulas[] = "$col IN (" . implode(',', array_fill(0, $n, '?')) . ")";
    }
    return empty($clausulas) ? '' : 'WHERE ' . implode(' AND ', $clausulas);
}
```

