function cacheLista(string $chamada, callable $fns): array {
    $dir = rtrim(sys_get_temp_dir(), '/');
    $key = sprintf('%s/%s.cache', $dir, md5($chamada));
    if (is_file($key)) {
        $info = json_decode(file_get_contents($key), true, 512, JSON_THROW_ON_ERROR);
