// ===== 2) Parse e validação dos filtros do formulário =====
function parseFiltros(): array
{
    $f = [
        'gre'     => [],
        'escola'  => [],
        'professor' => [],
        'turma'   => [],
    ];

    $raw = filter_input(INPUT_GET, 'gre');
    if (is_array($raw)) {
        $f['gre'] = array_filter(
