    }

    $raw = filter_input(INPUT_GET, 'escola');
    if (is_array($raw)) {
        $f['escola'] = array_filter(
            $raw,
            fn ($v) => trim((string) $v) !== '' && trim((string) $v) !== 'all'
        );
    }

    $raw = filter_input(INPUT_GET, 'professor');
    if (is_array($raw)) {
        $f['professor'] = array_filter(
