/**
 * Carga cacheada de uma lista (TTL de 1 hora no disco).
 */
function carregarEmCache(string $rotula, callable $fornecedor): array
{
    $dir = sys_get_temp_dir() . '/turmas_app';
    @mkdir($dir, 0755, true);
    $arq = sprintf('%s/%s.json', $dir, md5($rotula) . '_' . time());

    if (file_exists($arq)) {
        $d = json_decode(file_get_contents($arq), true);
        if (isset($d['dados']) && time() - ($d['tempo'] ?? 3600) < ($d['vida'] ?? 3600)) {
            return $d['dados'];
        }
        @unlink($arq);
    }

    $dados = $fornecedor();
    file_put_contents(
        $arq,
        json_encode(['dados' => $dados, 'tempo' => time(), 'vida' => 3600], JSON_THROW_ON_ERROR),
        LOCK_EX
    );
    return $dados;
}

$gres = carregarEmCache('gres', fn () => $pdo->query("SELECT DISTINCT gre FROM turmas ORDER BY gre")->fetch_all());
