```php
/**
 * Carrega uma lista de forma cacheada (arquivo temporário com TTL de 1 h).
 * Boa para listas que não mudam muito (ex.: relação de GREs).
 */
function cacheDaLista(string $nomeArquivo, callable $fornecedor): array
{
    $dir = sys_get_temp_dir() . '/turmas_app';
    @mkdir($dir, 0755, true);

    $arquivo = sprintf('%s/%s.cache', $dir, md5($nomeArquivo) . ':' . time());

    if (file_exists($arquivo)) {
        $d = json_decode(file_get_contents($arquivo), true);
        if (isset($d['dados']) && time() - ($d['timestamp'] ?? 3600) < ($d['duracao'] ?? 3600)) {
            return $d['dados'];
        }
        @unlink($arquivo);
    }

    $dados = $fornecedor();
    @mkdir($dir, 0755, true);
    file_put_contents(
        $arquivo,
        json_encode(['dados' => $dados, 'timestamp' => time(), 'duracao' => 3600], JSON_THROW_ON_ERROR),
        LOCK_EX
    );
    return $dados;
}

// Exemplo de uso (troque 'gres' por 'escolas_opcoes' etc. conforme a chave):
